using System.Globalization;
using System.Text;

namespace Fluid.Utils;

/// <summary>
/// Case mappings like Ruby's <c>String#upcase</c>, <c>downcase</c> and <c>capitalize</c>, which Liquid uses: the
/// full Unicode mappings (<c>SpecialCasing.txt</c>, e.g. <c>ß</c> to <c>SS</c>) and, for <c>capitalize</c>, the
/// titlecase of the first character (<c>ǆ</c> to <c>ǅ</c>).
/// </summary>
/// <remarks>
/// The tables only list the code points where Ruby 3.4 (Unicode 15.0) differs from .NET's invariant mappings,
/// generated by comparing both for every code point. The others use the culture's mappings, as before.
/// </remarks>
internal static class LiquidCase
{
    public static string ToUpper(string value, CultureInfo culture)
    {
        return IsAscii(value) ? value.ToUpper(culture) : Map(value, Upper, culture, upper: true);
    }

    public static string ToLower(string value, CultureInfo culture)
    {
        return IsAscii(value) ? value.ToLower(culture) : Map(value, Lower, culture, upper: false);
    }

    /// <summary>
    /// Like Ruby's <c>String#capitalize</c>: the titlecase of the first character, the rest in lower case.
    /// </summary>
    public static string Capitalize(string value, CultureInfo culture)
    {
        if (value.Length == 0)
        {
            return value;
        }

        var firstLength = char.IsSurrogatePair(value, 0) ? 2 : 1;
        var first = Title.TryGetValue(char.ConvertToUtf32(value, 0), out var title)
            ? title
            : value.Substring(0, firstLength).ToUpper(culture);

        var rest = value.Substring(firstLength);
        return first + (IsAscii(rest) ? rest.ToLower(culture) : Map(rest, Lower, culture, upper: false));
    }

    private static string Map(string value, Dictionary<int, string> special, CultureInfo culture, bool upper)
    {
        var builder = new StringBuilder(value.Length + 4);

        for (var i = 0; i < value.Length; i++)
        {
            if (char.IsSurrogatePair(value, i))
            {
                var pair = value.Substring(i, 2);
                builder.Append(special.TryGetValue(char.ConvertToUtf32(pair, 0), out var mappedPair)
                    ? mappedPair
                    : upper ? pair.ToUpper(culture) : pair.ToLower(culture));
                i++;
                continue;
            }

            var c = value[i];
            if (special.TryGetValue(c, out var mapped))
            {
                builder.Append(mapped);
            }
            else
            {
                builder.Append(upper ? char.ToUpper(c, culture) : char.ToLower(c, culture));
            }
        }

        return builder.ToString();
    }

    private static bool IsAscii(string value)
    {
#if NET8_0_OR_GREATER
        return Ascii.IsValid(value);
#else
        foreach (var c in value)
        {
            if (c >= 0x80)
            {
                return false;
            }
        }

        return true;
#endif
    }

